      module subroutine dashfs ( ctx, handle, nresvr, nresvc, ncomr, ncomc, free, lastla, lastrc, lastwd )
      use pepper_kinds, only: ip
      use pepper_inc_das
      use pepper_inc_errhnd
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! Handle of a DAS file.
      integer(ip), intent(out) :: free  !! Number of first free record.
      integer(ip), intent(out) :: lastla ( 3 )  !! Array of last logical addresses for each data
                                                !! type.
      integer(ip), intent(out) :: lastrc ( 3 )  !! Record number of last descriptor of each data
                                                !! type.
      integer(ip), intent(out) :: lastwd ( 3 )  !! Word number of last descriptor of each data
                                                !! type.
      integer(ip), intent(out) :: nresvr  !! Number of reserved records in file.
      integer(ip), intent(out) :: nresvc  !! Number of characters in use in reserved rec. area.
      integer(ip), intent(out) :: ncomr  !! Number of comment records in file.
      integer(ip), intent(out) :: ncomc  !! Number of characters in use in comment area.
      integer(ip), parameter :: next   ( 3 ) = &
         [ 2, 3, 1 ]
      integer(ip), parameter :: prev   ( 3 ) = &
         [ 3, 1, 2 ]
      character(acclen) :: acc
      character(fmtlen) :: format
      character(idwlen) :: idword
      character(ifnlen) :: locifn
      character(fmtlen) :: locfmt
      character(tailen) :: tail
      character(typlen) :: ttype
      integer(ip) :: curtyp
      integer(ip) :: dirrec ( nwi )
      integer(ip) :: dsctyp
      integer(ip) :: endrec
      integer(ip) :: fnb
      integer(ip) :: findex
      integer(ip) :: i
      integer(ip) :: inqsta
      integer(ip) :: iostat
      integer(ip) :: last
      integer(ip) :: ldrec  ( 3 )
      integer(ip) :: ldrmax
      integer(ip) :: loc
      integer(ip) :: loccch
      integer(ip) :: loccrc
      integer(ip) :: locrrc
      integer(ip) :: locrch
      integer(ip) :: maxadr
      integer(ip) :: new
      integer(ip) :: nrec
      integer(ip) :: number
      integer(ip), parameter :: nw     ( 3 ) = &
         [ nwc, nwd, nwi ]
      integer(ip) :: nxtdir
      integer(ip) :: nxtrec
      integer(ip) :: prvtyp
      integer(ip) :: type
      logical :: found
      associate ( ft => ctx%spice%dasfm )
!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

      findex  =  ft%find ( handle )

      found   =  findex > 0

      if ( found ) then
!
!        Give the caller the current summary from the file table.
!
         nresvr  =  ft%files(findex)%summary(rrcidx)
         nresvc  =  ft%files(findex)%summary(rchidx)
         ncomr   =  ft%files(findex)%summary(crcidx)
         ncomc   =  ft%files(findex)%summary(cchidx)
         free    =  ft%files(findex)%summary(freidx)

         do i = 1, 3
            lastla(i)  =  ft%files(findex)%summary(llabas + i)
            lastrc(i)  =  ft%files(findex)%summary(lrcbas + i)
            lastwd(i)  =  ft%files(findex)%summary(lwdbas + i)
         end do

      else
         call ctx%setmsg ( 'There is no DAS file open with handle = #' )
         call ctx%errint ( '#', handle                                 )
         call ctx%sigerr ( 'SPICE(DASNOSUCHHANDLE)'                    )
      end if

      return
      end associate
      end subroutine dashfs

      !> Update the file summary in a specified DAS file.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE   is the handle of a previously opened DAS file.
      !>
      !>     NRESVR   is the number of reserved records in a specified DAS
      !>              file.
      !>
      !>     NRESVC   is the number of characters in use in the reserved
      !>              record area of a specified DAS file.
      !>
      !>     NCOMR    is the number of comment records in a specified DAS
      !>              file.
      !>
      !>     NCOMC    is the number of characters in use in the comment area
      !>              of a specified DAS file.
      !>
      !>     FREE     is the Fortran record number of the first free record
      !>              in a specified DAS file.
      !>
      !>     LASTLA   is an array containing the highest current logical
      !>              addresses, in the specified DAS file, of data of
      !>              character, double precision, and integer types, in
      !>              that order.
      !>
      !>     LASTRC   is an array containing the Fortran record numbers, in
      !>              the specified DAS file, of the directory records
      !>              containing the current last descriptors of clusters
      !>              of character, double precision, and integer data
      !>              records, in that order.
      !>
      !>     LASTWD   is an array containing the word positions, in the
      !>              specified DAS file, of the current last descriptors
      !>              of clusters of character, double precision, and
      !>              integer data records, in that order.
      !>
      !>## Detailed Output
      !>
      !>     None. See $Particulars for a description of the effect of this
      !>     routine.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If the specified handle does not belong to any file that is
      !>         currently known to be open, the error SPICE(DASNOSUCHHANDLE)
      !>         is signaled.
      !>
      !>     2)  If the specified handle is not open for WRITE access, the
      !>         error SPICE(DASINVALIDACCESS) is signaled.
      !>
      !>     3)  If this routine's attempts to read the DAS file record
      !>         fail before an update, the error SPICE(DASREADFAIL) is
      !>         signaled.
      !>
      !>     4)  If the attempt to write to the DAS file record fails, the
      !>         error SPICE(DASWRITEFAIL) is signaled.
      !>
      !>## Files
      !>
      !>     See the description of the argument HANDLE in $Detailed_Input.
      !>
      !>## Particulars
      !>
      !>     The quantities NRESVR, NRESRC, NCOMR, NCOMC, FREE, LASTLA,
      !>     LASTRC, and LASTWD define the `state' of a DAS file, and in
      !>     particular the state of the directory structure of the file.
      !>     These quantities should normally be updated only by DAS routines.
      !>
      !>     The higher-level DAS routines that affect a DAS file's summary,
      !>     such as
      !>
      !>        DASADx
      !>        DASUDx
      !>        DASARR
      !>
      !>     automatically update the file summary, so there is no need for
      !>     the calling program to perform the update explicitly.
      !>
      !>## Examples
      !>
      !>     1)  Update the last d.p. logical address for a DAS file, leaving
      !>         the rest of the file summary intact.
      !>
      !>            C
      !>            C     Read the file summary.
      !>            C
      !>                  CALL DASHFS ( HANDLE,
      !>                 .              NRESVR,
      !>                 .              RRESVC,
      !>                 .              NCOMR,
      !>                 .              NCOMC,
      !>                 .              FREE,
      !>                 .              LASTLA,
      !>                 .              LASTRC,
      !>                 .              LASTWD )
      !>
      !>            C
      !>            C     Update the d.p. component of the `last logical
      !>            C     address' array.
      !>            C
      !>                  LASTLA(DP) = NEWVAL
      !>
      !>                  CALL DASUFS ( HANDLE,
      !>                 .              NRESVR,
      !>                 .              RRESVC,
      !>                 .              NCOMR,
      !>                 .              NCOMC,
      !>                 .              FREE,
      !>                 .              LASTLA,
      !>                 .              LASTRC,
      !>                 .              LASTWD )
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     K.R. Gehringer     (JPL)
      !>     B.V. Semenov       (JPL)
      !>     W.L. Taber         (JPL)
      !>     F.S. Turner        (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 7.1.1, 19-JUL-2021 (JDR)
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>-    SPICELIB Version 7.1.0, 07-OCT-2015 (NJB)
      !>
      !>        Corrected call to ZZDDHCLS.
      !>
      !>-    SPICELIB Version 7.0.0, 30-JUL-2014 (NJB)
      !>
      !>        Now uses DAF/DAS handle manager subsystem.
      !>
      !>-    SPICELIB Version 6.1.0, 26-SEP-2005 (NJB)
      !>
      !>        Bug fix: file name is now correctly inserted into long
      !>        error message generated when target file is not open for
      !>        write access.
      !>
      !>-    SPICELIB Version 6.0.1, 17-JUL-2002 (BVS)
      !>
      !>        Added MAC-OSX environments.
      !>
      !>-    SPICELIB Version 6.0.0, 15-OCT-2001 (FST) (NJB)
      !>
      !>        Bug fix: this routine now reads the file record
      !>        before attempting to update it. The buffered values
      !>        of IDWORD and IFN are no longer present.
      !>
      !>        Bug fix: missing call to CHKIN was added to an error
      !>        handling branch in entry point DASUFS. This call is
      !>        required because DASUFS uses discovery check-in.
      !>
      !>-    SPICELIB Version 5.0.4, 08-OCT-1999 (WLT)
      !>
      !>        The environment lines were expanded so that the supported
      !>        environments are now explicitly given. New
      !>        environments are WIN-NT
      !>
      !>-    SPICELIB Version 5.0.3, 16-SEP-1999 (NJB)
      !>
      !>        CSPICE environments were added. Some typos were corrected.
      !>
      !>-    SPICELIB Version 5.0.2, 28-JUL-1999 (WLT)
      !>
      !>        The environment lines were expanded so that the supported
      !>        environments are now explicitly given. New
      !>        environments are PC-DIGITAL, SGI-O32 and SGI-N32.
      !>
      !>-    SPICELIB Version 5.0.1, 18-MAR-1999 (WLT)
      !>
      !>        The environment lines were expanded so that the supported
      !>        environments are now explicitly given. Previously,
      !>        environments such as SUN-SUNOS and SUN-SOLARIS were implied
      !>        by the environment label SUN.
      !>
      !>-    SPICELIB Version 1.0.1, 01-NOV-1993 (KRG)
      !>
      !>        Removed references to specific DAS file open routines in the
      !>        $Detailed_Input section of the header. This was done in order
      !>        to minimize documentation changes if these open routines ever
      !>        change.
      !>
      !>-    SPICELIB Version 1.0.0, 30-JUL-1992 (NJB) (WLT)
      !>
      !>## Revisions
      !>
      !>-    SPICELIB Version 6.1.0, 26-SEP-2005 (NJB)
      !>
      !>        Bug fix: file name is now correctly inserted into long
      !>        error message generated when target file is not open for
      !>        write access.
      !>
      !>-    SPICELIB Version 5.1.0, 15-OCT-2001 (NJB)
      !>
      !>        Bug fix: missing call to CHKIN was added to an error
      !>        handling branch in entry point DASUFS. This call is
      !>        required because DASUFS uses discovery check-in.
      !>
      !>-    SPICELIB Version 1.0.1, 01-NOV-1993 (KRG)
      !>
      !>        Removed references to specific DAS file open routines in the
      !>        $Detailed_Input section of the header. This was done in order
      !>        to minimize documentation changes if these open routines ever
      !>        change.
      !>
      !>-    SPICELIB Version 1.0.0, 30-JUL-1992 (NJB) (WLT)
      module subroutine dasufs ( ctx, handle, nresvr, nresvc, ncomr, ncomc, free, lastla, lastrc, lastwd )
      use pepper_kinds, only: ip
      use pepper_inc_das
      use pepper_inc_errhnd
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! Handle of an open DAS file.
      integer(ip), intent(in) :: free  !! Number of first free record.
      integer(ip), intent(in) :: lastla ( 3 )  !! Array of last logical addresses for each data
                                               !! type.
      integer(ip), intent(in) :: lastrc ( 3 )  !! Record number of last descriptor of each data
                                               !! type.
      integer(ip), intent(in) :: lastwd ( 3 )  !! Word number of last descriptor of each data
                                               !! type.
      integer(ip), intent(in) :: nresvr  !! Number of reserved records in file.
      integer(ip), intent(in) :: nresvc  !! Number of characters in use in reserved rec. area.
      integer(ip), intent(in) :: ncomr  !! Number of comment records in file.
      integer(ip), intent(in) :: ncomc  !! Number of characters in use in comment area.
      integer(ip), parameter :: read = 1
      integer(ip), parameter :: write = read  + 1
      integer(ip), parameter :: next   ( 3 ) = &
         [ 2, 3, 1 ]
      integer(ip), parameter :: prev   ( 3 ) = &
         [ 3, 1, 2 ]
      character(acclen) :: acc
      character(fmtlen) :: format
      character(idwlen) :: idword
      character(:), allocatable :: locdas
      character(ifnlen) :: locifn
      character(fmtlen) :: locfmt
      character(tailen) :: tail
      character(typlen) :: ttype
      integer(ip) :: curtyp
      integer(ip) :: dirrec ( nwi )
      integer(ip) :: dsctyp
      integer(ip) :: endrec
      integer(ip) :: fnb
      integer(ip) :: findex
      integer(ip) :: i
      integer(ip) :: inqsta
      integer(ip) :: iostat
      integer(ip) :: last
      integer(ip) :: ldrec  ( 3 )
      integer(ip) :: ldrmax
      integer(ip) :: loc
      integer(ip) :: loccch
      integer(ip) :: loccrc
      integer(ip) :: locrrc
      integer(ip) :: locrch
      integer(ip) :: maxadr
      integer(ip) :: new
      integer(ip) :: nrec
      integer(ip) :: number
      integer(ip), parameter :: nw     ( 3 ) = &
         [ nwc, nwd, nwi ]
      integer(ip) :: nxtdir
      integer(ip) :: nxtrec
      integer(ip) :: prvtyp
      integer(ip) :: type
      logical :: found
      associate ( ft => ctx%spice%dasfm )
!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Find the file table entries for this file.
!
      findex  =  ft%find ( handle )
      found   =  findex > 0

      if ( found ) then
!
!        Obtain a logical unit for this file.
!
         call zzddhhlu ( ctx, handle, 'DAS', .false., number )

         if ( ctx%failed() ) return

!
!        Now check to see that HANDLE is open for write, as one has
!        no business updating a file summary for files that are
!        open for read access only.
!
         if ( ft%files(findex)%access /= write ) then

            call ctx%setmsg ( 'DAS file not open for writing. Handle = #,' &
            //            ' file = ''#''.'                             )
            call ctx%errint ( '#', handle                                  )
            call ctx%errfnm ( '#', number                                  )
            call ctx%sigerr ( 'SPICE(DASINVALIDACCESS)'                    )
            return

         end if

!
!        If any of the counts pertaining to the reserved record are or
!        the comment area were changed, we need to record the new
!        counts in the file record.  Otherwise, leave the file alone.
!
         if (      (  nresvr /= ft%files(findex)%summary(rrcidx)  ) &
              .or. (  nresvc /= ft%files(findex)%summary(rchidx)  ) &
              .or. (  ncomr  /= ft%files(findex)%summary(crcidx)  ) &
              .or. (  ncomc  /= ft%files(findex)%summary(cchidx)  )   )  then

!
!           Read the file record.
!
            read ( number, &
                   rec    = 1, &
                   iostat = iostat )  idword, &
                                      locifn, &
                                      locrrc, &
                                      locrch, &
                                      loccrc, &
                                      loccch, &
                                      locfmt, &
                                      tail

            if ( iostat /= 0 ) then

               call ctx%setmsg ( 'Attempt to read file record failed. ' &
               //            'File was ''#''.  Value of IOSTAT was' &
               //            ' ''#''.'                              )
               call ctx%errfnm ( '#', number                            )
               call ctx%errint ( '#', iostat                            )
               call ctx%sigerr ( 'SPICE(DASREADFAIL)'                   )
               return

            end if

            write ( number, &
                    rec     =  1, &
                    iostat  =  iostat )  idword, &
                                         locifn, &
                                         nresvr, &
                                         nresvc, &
                                         ncomr, &
                                         ncomc, &
                                         locfmt, &
                                         tail
            flush ( number )
            call files_written ( ctx )

            if ( iostat /= 0 ) then
!
!              Try to obtain the DAS file's name.
!
               locdas = file_name ( ctx%spice, handle )

               call zzddhcls ( ctx, handle, 'DAS', .false. )

               if ( ctx%failed() ) return

               call ctx%setmsg ( 'Attempt to update file record failed. ' &
               //            'File was ''#''.  Value of IOSTAT was' &
               //             ' ''#''.'                                )
               call ctx%errch  ( '#', locdas                               )
               call ctx%errint ( '#', iostat                               )
               call ctx%sigerr ( 'SPICE(DASWRITEFAIL)'                     )
               return

            end if

         end if

!
!        Update the file table.
!
         ft%files(findex)%summary(rrcidx)  =  nresvr
         ft%files(findex)%summary(rchidx)  =  nresvc
         ft%files(findex)%summary(crcidx)  =  ncomr
         ft%files(findex)%summary(cchidx)  =  ncomc
         ft%files(findex)%summary(freidx)  =  free

         do i = 1, 3
            ft%files(findex)%summary(llabas + i)  =  lastla(i)
            ft%files(findex)%summary(lrcbas + i)  =  lastrc(i)
            ft%files(findex)%summary(lwdbas + i)  =  lastwd(i)
         end do

      else

         call ctx%setmsg ( 'There is no file open with handle = #' )
         call ctx%errint ( '#', handle                             )
         call ctx%sigerr ( 'SPICE(DASNOSUCHHANDLE)'                )
         return

      end if

      return
      end associate
      end subroutine dasufs

      !> Return the logical unit associated with a handle. The unit
      !> is "locked" to the handle by the DAF/DAS handle manager
      !> subsystem.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE   is the handle of a previously opened DAS file.
      !>
      !>## Detailed Output
      !>
      !>     UNIT     is the Fortran logical unit to which the file is
      !>              connected.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If the specified handle does not belong to any file that is
      !>         currently known to be open, the error SPICE(DASNOSUCHHANDLE)
      !>         is signaled.
      !>
      !>## Files
      !>
      !>     See the description of the argument HANDLE in $Detailed_Input.
      !>
      !>## Particulars
      !>
      !>     This routine is a utility used by the DAS system to support
      !>     file I/O. DASHLU may also prove useful to general SPICELIB
      !>     users for constructing error messages.
      !>
      !>## Examples
      !>
      !>     1)  Obtain the logical unit associated with a DAS file having
      !>         a known handle.
      !>
      !>            CALL DASHLU ( HANDLE, UNIT )
      !>
      !>## Restrictions
      !>
      !>     1)  Successfully invoking this module has the side effect of
      !>         locking UNIT to HANDLE. This 'lock' guarantees until
      !>         HANDLE is closed (or unlocked) that the file associated
      !>         with HANDLE is always open and attached to logical unit
      !>         UNIT. To unlock a handle without closing the file, use
      !>         ZZDDHUNL, an entry point in the handle manager umbrella,
      !>         ZZDDHMAN.
      !>
      !>         The system can lock at most UTSIZE-SCRUNT-RSVUNT
      !>         simultaneously (see the include file 'zzddhman.inc' for
      !>         specific values of these parameters), but unnecessarily
      !>         locking handles to their logical units may cause performance
      !>         degradation. The handle manager will have fewer logical
      !>         units to utilize when disconnecting and reconnecting
      !>         loaded files.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     K.R. Gehringer     (JPL)
      !>     B.V. Semenov       (JPL)
      !>     W.L. Taber         (JPL)
      !>     F.S. Turner        (JPL)
      !>     I.M. Underwood     (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 7.0.1, 19-JUL-2021 (JDR)
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>-    SPICELIB Version 7.0.0, 04-FEB-2015 (NJB) (FST)
      !>
      !>        Now uses DAF/DAS handle manager subsystem.
      !>        Note that this routine is now considered obsolete.
      !>
      !>-    SPICELIB Version 6.0.1, 17-JUL-2002 (BVS)
      !>
      !>        Added MAC-OSX environments.
      !>
      !>-    SPICELIB Version 5.0.4, 08-OCT-1999 (WLT)
      !>
      !>        The environment lines were expanded so that the supported
      !>        environments are now explicitly given. New
      !>        environments are WIN-NT
      !>
      !>-    SPICELIB Version 5.0.3, 16-SEP-1999 (NJB)
      !>
      !>        CSPICE environments were added. Some typos were corrected.
      !>
      !>-    SPICELIB Version 5.0.2, 28-JUL-1999 (WLT)
      !>
      !>        The environment lines were expanded so that the supported
      !>        environments are now explicitly given. New
      !>        environments are PC-DIGITAL, SGI-O32 and SGI-N32.
      !>
      !>-    SPICELIB Version 5.0.1, 18-MAR-1999 (WLT)
      !>
      !>        The environment lines were expanded so that the supported
      !>        environments are now explicitly given. Previously,
      !>        environments such as SUN-SUNOS and SUN-SOLARIS were implied
      !>        by the environment label SUN.
      !>
      !>-    SPICELIB Version 1.0.1, 01-NOV-1993 (KRG)
      !>
      !>        Removed references to specific DAS file open routines in the
      !>        $Detailed_Input section of the header. This was done in order
      !>        to minimize documentation changes if these open routines ever
      !>        change.
      !>
      !>-    SPICELIB Version 1.0.0, 11-NOV-1992 (NJB) (WLT) (IMU)
      !>
      !>## Revisions
      !>
      !>-    SPICELIB Version 1.0.1, 01-NOV-1993 (KRG)
      !>
      !>        Removed references to specific DAS file open routines in the
      !>        $Detailed_Input section of the header. This was done in order
      !>        to minimize documentation changes if these open routines ever
      !>        change.
      !>
      !>-    SPICELIB Version 1.0.0, 11-NOV-1992 (NJB) (WLT) (IMU)
      module subroutine dashlu ( ctx, handle, unit )
      use pepper_kinds, only: ip
      use pepper_inc_das
      use pepper_inc_errhnd
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! Handle of a DAS file.
      integer(ip), intent(out) :: unit  !! Corresponding logical unit.
      integer(ip), parameter :: next   ( 3 ) = &
         [ 2, 3, 1 ]
      integer(ip), parameter :: prev   ( 3 ) = &
         [ 3, 1, 2 ]
      character(acclen) :: acc
      character(fmtlen) :: format
      character(idwlen) :: idword
      character(ifnlen) :: locifn
      character(fmtlen) :: locfmt
      character(tailen) :: tail
      character(typlen) :: ttype
      integer(ip) :: curtyp
      integer(ip) :: dirrec ( nwi )
      integer(ip) :: dsctyp
      integer(ip) :: endrec
      integer(ip) :: fnb
      integer(ip) :: findex
      integer(ip) :: i
      integer(ip) :: inqsta
      integer(ip) :: iostat
      integer(ip) :: last
      integer(ip) :: ldrec  ( 3 )
      integer(ip) :: ldrmax
      integer(ip) :: loc
      integer(ip) :: loccch
      integer(ip) :: loccrc
      integer(ip) :: locrrc
      integer(ip) :: locrch
      integer(ip) :: maxadr
      integer(ip) :: new
      integer(ip) :: nrec
      integer(ip) :: number
      integer(ip), parameter :: nw     ( 3 ) = &
         [ nwc, nwd, nwi ]
      integer(ip) :: nxtdir
      integer(ip) :: nxtrec
      integer(ip) :: prvtyp
      integer(ip) :: type
      logical :: found
      associate ( ft => ctx%spice%dasfm )
!
!     We use discovery check-ins in this routine.
!
      if ( ctx%failed() ) return

!
!     Find the file table entries for this file.
!
      findex  =  ft%find ( handle )
      found   =  findex > 0

      if ( found ) then
!
!        For backward compatibility, the logical unit must be
!        locked to the file.
!
         call zzddhhlu ( ctx, handle, 'DAS', .true., unit )

      else

         call ctx%setmsg ( 'There is no file open with handle = #' )
         call ctx%errint ( '#', handle                             )
         call ctx%sigerr ( 'SPICE(DASNOSUCHHANDLE)'                )

      end if

      return
      end associate
      end subroutine dashlu

      !> Return the handle associated with a logical unit.
      !>
      !>## Detailed Input
      !>
      !>     UNIT     is the logical unit to which a DAS file has been
      !>              connected when it was opened.
      !>
      !>## Detailed Output
      !>
      !>     HANDLE   is the handle associated with the file.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If the specified unit is not connected to any DAS file that is
      !>         currently known to be open, the error SPICE(DASNOSUCHUNIT)
      !>         is signaled.
      !>
      !>## Files
      !>
      !>     See the description of the argument HANDLE in $Detailed_Input.
      !>
      !>## Particulars
      !>
      !>     It is unlikely, but possible, that a calling program would know
      !>     the logical unit to which a file is connected without knowing the
      !>     handle associated with the file. DASLUH is provided mostly for
      !>     completeness.
      !>
      !>## Examples
      !>
      !>     In the following code fragment, the handle associated with
      !>     a DAS file is retrieved using the logical unit to which the
      !>     file is connected. The handle is then used to determine the
      !>     name of the file.
      !>
      !>        CALL DASLUH ( UNIT,   HANDLE )
      !>        CALL DASHFN ( HANDLE, FNAME  )
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     K.R. Gehringer     (JPL)
      !>     B.V. Semenov       (JPL)
      !>     W.L. Taber         (JPL)
      !>     I.M. Underwood     (JPL)
      !>
      !>## Version
