      !>
      !>## Revisions
      !>
      !>-    SPICELIB Version 1.0.1, 01-NOV-1993 (KRG)
      !>
      !>        Removed references to specific DAS file open routines in the
      !>        $Detailed_Input section of the header. This was done in order
      !>        to minimize documentation changes if these open routines ever
      !>        change.
      !>
      !>-    SPICELIB Version 1.0.0, 11-NOV-1992 (NJB) (WLT) (IMU)
      module subroutine dashfn ( ctx, handle, fname )
      use pepper_kinds, only: ip
      use pepper_inc_das
      use pepper_inc_errhnd
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      character(*), intent(out) :: fname  !! Corresponding file name.
      integer(ip), intent(in) :: handle  !! Handle of a DAS file.
      integer(ip), parameter :: next   ( 3 ) = &
         [ 2, 3, 1 ]
      integer(ip), parameter :: prev   ( 3 ) = &
         [ 3, 1, 2 ]
      character(acclen) :: acc
      character(fmtlen) :: format
      character(idwlen) :: idword
      character(ifnlen) :: locifn
      character(fmtlen) :: locfmt
      character(tailen) :: tail
      character(typlen) :: ttype
      integer(ip) :: curtyp
      integer(ip) :: dirrec ( nwi )
      integer(ip) :: dsctyp
      integer(ip) :: endrec
      integer(ip) :: fnb
      integer(ip) :: findex
      integer(ip) :: i
      integer(ip) :: inqsta
      integer(ip) :: iostat
      integer(ip) :: last
      integer(ip) :: ldrec  ( 3 )
      integer(ip) :: ldrmax
      integer(ip) :: loc
      integer(ip) :: loccch
      integer(ip) :: loccrc
      integer(ip) :: locrrc
      integer(ip) :: locrch
      integer(ip) :: maxadr
      integer(ip) :: new
      integer(ip) :: nrec
      integer(ip) :: number
      integer(ip), parameter :: nw     ( 3 ) = &
         [ nwc, nwd, nwi ]
      integer(ip) :: nxtdir
      integer(ip) :: nxtrec
      integer(ip) :: prvtyp
      integer(ip) :: type
      logical :: found
      associate ( ft => ctx%spice%dasfm )
!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Find the file table entries for this file.
!
      findex  =  ft%find ( handle )
      found   =  findex > 0

      if ( found ) then

         call zzddhhlu ( ctx, handle, 'DAS', .false., number )

         inquire ( unit = number, &
                   name = fname  )

      else

         call ctx%setmsg ( 'There is no DAS file open with handle = #' )
         call ctx%errint ( '#', handle                                 )
         call ctx%sigerr ( 'SPICE(DASNOSUCHHANDLE)'                    )

      end if

      return
      end associate
      end subroutine dashfn

      !> Return handle associated with a file name.
      !>
      !>## Detailed Input
      !>
      !>     FNAME    is the name of a previously opened DAS file.
      !>
      !>## Detailed Output
      !>
      !>     HANDLE   is the handle associated with the file.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If the specified name does not specify any DAS file currently
      !>         known to be open, the error SPICE(DASNOSUCHFILE) is signaled.
      !>
      !>## Files
      !>
      !>     See the description of the argument HANDLE in $Detailed_Input.
      !>
      !>## Particulars
      !>
      !>     It is sometimes easier to work with file names (which are
      !>     meaningful, and often predictable) than with file handles
      !>     (which are neither), especially in interactive situations.
      !>     However, nearly every DAS routine requires that you use file
      !>     handles to refer to files. DASFNH is provided to bridge the gap
      !>     between the two representations.
