      module subroutine dashof ( ctx, fhset )
      use pepper_arrays, only: shelli
      use pepper_kinds, only: ip
      use pepper_inc_das
      use pepper_inc_errhnd
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(inout) :: fhset  ( lbcell : * )  !! A set containing handles of
                                                           !! currently
                                                         !! open DAS files.
      integer(ip), parameter :: next   ( 3 ) = &
         [ 2, 3, 1 ]
      integer(ip), parameter :: prev   ( 3 ) = &
         [ 3, 1, 2 ]
      character(acclen) :: acc
      character(fmtlen) :: format
      character(idwlen) :: idword
      character(ifnlen) :: locifn
      character(fmtlen) :: locfmt
      character(tailen) :: tail
      character(typlen) :: ttype
      integer(ip) :: curtyp
      integer(ip) :: dirrec ( nwi )
      integer(ip) :: dsctyp
      integer(ip) :: endrec
      integer(ip) :: fnb
      integer(ip) :: findex
      integer(ip) :: i
      integer(ip) :: inqsta
      integer(ip) :: iostat
      integer(ip) :: last
      integer(ip) :: ldrec  ( 3 )
      integer(ip) :: ldrmax
      integer(ip) :: loc
      integer(ip) :: loccch
      integer(ip) :: loccrc
      integer(ip) :: locrrc
      integer(ip) :: locrch
      integer(ip) :: maxadr
      integer(ip) :: new
      integer(ip) :: nrec
      integer(ip) :: number
      integer(ip), parameter :: nw     ( 3 ) = &
         [ nwc, nwd, nwi ]
      integer(ip) :: nxtdir
      integer(ip) :: nxtrec
      integer(ip) :: prvtyp
      integer(ip) :: type
      logical :: found
      associate ( ft => ctx%spice%dasfm )
      if ( ctx%failed() ) return

!
!     Just stuff our local list into the set.
!
      block
!
!        PEPPER: the set is built from the file table (SPICELIB kept it
!        as FHLIST); COPYI signals SPICE(CELLTOOSMALL) as before if
!        FHSET has no room.
!
         integer(ip), allocatable :: set(:)
         integer(ip) :: k
         allocate ( set(lbcell:max(1_ip, ft%nft)) )
         call ssizei ( ctx, max(1_ip, ft%nft), set )
         do k = 1, ft%nft
            set(k) = ft%files(k)%handle
         end do
         call shelli ( ft%nft, set(1:) )
         call scardi ( ctx, ft%nft, set )
         call copyi ( ctx, set, fhset )
      end block

      return
      end associate
      end subroutine dashof

      !> Signal an error if a DAS file file handle does not designate a
      !> DAS file that is open for a specified type of access.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE   is a DAS file handle to validate. For HANDLE to be
      !>              considered valid, it must specify a DAS file that
      !>              is open for the type of access specified by the
      !>              input argument ACCESS.
      !>
      !>     ACCESS   is a string indicating the type of access that
      !>              the DAS file specified by the input argument HANDLE
      !>              must be open for. The values of ACCESS may be
      !>
      !>                 'READ'      File must be open for read access
      !>                             by DAS routines. DAS files opened
      !>                             for read or write access may be
      !>                             read.
      !>
      !>                 'WRITE'     File must be open for write access
      !>                             by DAS routines. Note that files
      !>                             open for write access may be read as
      !>                             well as written.
      !>
      !>              Leading and trailing blanks in ACCESS are ignored,
      !>              and case is not significant.
      !>
      !>## Detailed Output
      !>
      !>     None. See $Particulars for a description of the effect of this
      !>     routine.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If the input argument ACCESS has an unrecognized value,
      !>         the error SPICE(INVALIDOPTION) is signaled.
      !>
      !>## Files
      !>
      !>     None.
      !>
      !>## Particulars
      !>
      !>     This routine signals the error SPICE(DASINVALIDACCESS) if the
      !>     DAS designated by the input argument HANDLE is not open
      !>     for the specified type of access. If HANDLE does not designate
      !>     an open DAS file, the error SPICE(DASNOSUCHHANDLE) is signaled.
      !>
      !>     This routine allows subroutines to test file handles for
      !>     validity before attempting to access the files they designate,
      !>     or before performing operations on the handles themselves, such
      !>     as finding the name of the file designated by a handle. This
      !>     routine should be used in situations where the appropriate action
      !>     to take upon determining that a handle is invalid is to signal
      !>     an error. DASSIH centralizes the error response for this type of
      !>     error in a single routine.
      !>
      !>     In cases where it is necessary to determine the validity of a
      !>     file handle, but it is not an error for the handle to refer
      !>     to a closed file, the entry point DASHOF should be used instead
      !>     of DASSIH.
      !>
      !>## Examples
      !>
      !>     1)  Make sure that a file handle designates a DAS file that can
      !>         be read. Signal an error if not.
      !>
      !>         Note that if a DAS file is open for reading or writing, read
      !>         access is allowed.
      !>
      !>                  CALL DASSIH ( HANDLE, 'READ' )
      !>
      !>                  IF ( FAILED() ) THEN
      !>                     RETURN
      !>                  END IF
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     K.R. Gehringer     (JPL)
      !>     B.V. Semenov       (JPL)
      !>     W.L. Taber         (JPL)
      !>     I.M. Underwood     (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 6.1.1, 19-JUL-2021 (JDR)
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>-    SPICELIB Version 6.1.0, 26-SEP-2005 (NJB)
      !>
      !>        Local variable DAS was renamed to DASFIL. This
      !>        was done to avoid future conflict with parameters
      !>        in zzddhman.inc.
      !>
      !>-    SPICELIB Version 6.0.1, 17-JUL-2002 (BVS)
      !>
      !>        Added MAC-OSX environments.
      !>
      !>-    SPICELIB Version 5.0.4, 08-OCT-1999 (WLT)
      !>
      !>        The environment lines were expanded so that the supported
      !>        environments are now explicitly given. New
      !>        environments are WIN-NT
      !>
      !>-    SPICELIB Version 5.0.3, 16-SEP-1999 (NJB)
      !>
      !>        CSPICE environments were added. Some typos were corrected.
      !>
      !>-    SPICELIB Version 5.0.2, 28-JUL-1999 (WLT)
      !>
      !>        The environment lines were expanded so that the supported
      !>        environments are now explicitly given. New
      !>        environments are PC-DIGITAL, SGI-O32 and SGI-N32.
      !>
      !>-    SPICELIB Version 5.0.1, 18-MAR-1999 (WLT)
      !>
      !>        The environment lines were expanded so that the supported
      !>        environments are now explicitly given. Previously,
      !>        environments such as SUN-SUNOS and SUN-SOLARIS were implied
      !>        by the environment label SUN.
      !>
      !>-    SPICELIB Version 1.0.1, 01-NOV-1993 (KRG)
      !>
      !>        Removed references to specific DAS file open routines in the
      !>        $Detailed_Input section of the header. This was done in order
      !>        to minimize documentation changes if these open routines ever
      !>        change.
      !>
      !>-    SPICELIB Version 1.0.0, 11-NOV-1992 (NJB) (WLT) (IMU)
      !>
      !>## Revisions
      !>
      !>-    SPICELIB Version 6.1.0, 26-SEP-2005 (NJB)
      !>
      !>        Local variable DAS was renamed to DASFIL. This
      !>        was done to avoid future conflict with parameters
      !>        in zzddhman.inc.
      !>
      !>-    SPICELIB Version 1.0.1, 01-NOV-1993 (KRG)
      !>
      !>        Removed references to specific DAS file open routines in the
      !>        $Detailed_Input section of the header. This was done in order
      !>        to minimize documentation changes if these open routines ever
      !>        change.
      !>
      !>-    SPICELIB Version 1.0.0, 11-NOV-1992 (NJB) (WLT) (IMU)
      module subroutine dassih ( ctx, handle, access )
      use pepper_kinds, only: ip
      use pepper_strings, only: ucase_inplace
      use pepper_inc_das
      use pepper_inc_errhnd
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! HANDLE to be validated.
      character(*), intent(in) :: access  !! String indicating access type.
      integer(ip), parameter :: read = 1
      integer(ip), parameter :: write = read  + 1
      integer(ip), parameter :: next   ( 3 ) = &
         [ 2, 3, 1 ]
      integer(ip), parameter :: prev   ( 3 ) = &
         [ 3, 1, 2 ]
      character(acclen) :: acc
      character(fmtlen) :: format
      character(idwlen) :: idword
      character(ifnlen) :: locifn
      character(fmtlen) :: locfmt
      character(tailen) :: tail
      character(typlen) :: ttype
      integer(ip) :: curtyp
      integer(ip) :: dirrec ( nwi )
      integer(ip) :: dsctyp
      integer(ip) :: endrec
      integer(ip) :: fnb
      integer(ip) :: findex
      integer(ip) :: i
      integer(ip) :: inqsta
      integer(ip) :: iostat
      integer(ip) :: last
      integer(ip) :: ldrec  ( 3 )
      integer(ip) :: ldrmax
      integer(ip) :: loc
      integer(ip) :: loccch
      integer(ip) :: loccrc
      integer(ip) :: locrrc
      integer(ip) :: locrch
      integer(ip) :: maxadr
      integer(ip) :: new
      integer(ip) :: nrec
      integer(ip) :: number
      integer(ip), parameter :: nw     ( 3 ) = &
         [ nwc, nwd, nwi ]
      integer(ip) :: nxtdir
      integer(ip) :: nxtrec
      integer(ip) :: prvtyp
      integer(ip) :: type
      logical :: found
      associate ( ft => ctx%spice%dasfm )
!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Get an upper case, left-justified copy of ACCESS.
!
      acc = adjustl(access)
      call ucase_inplace ( acc )

!
!     Make sure we recognize the access type specified by the caller.
!
      if (  ( acc /= 'READ' ) .and. ( acc /= 'WRITE' )  ) then

         call ctx%setmsg ( 'Unrecognized access type.  Type was #. ' )
         call ctx%errch  ( '#', access                               )
         call ctx%sigerr ( 'SPICE(INVALIDOPTION)'                    )
         return

      end if

!
!     See whether the input handle is in our list at all.  It's
!     unlawful for the handle to be absent.
!
      if (  ft%find ( handle ) == 0  )  then

         call ctx%setmsg ( 'Handle # is not attached to an open DAS file.' )
         call ctx%errint ( '#', handle                                     )
         call ctx%sigerr ( 'SPICE(DASNOSUCHHANDLE)'                        )
         return

      else
!
!        Find the file table entries for this file.  We know they
!        must exist.
!
         findex  =  ft%find ( handle )
         found   =  findex > 0
!
!        At this point, FINDEX points to the file table entries
!        for this file.
!

         if (       ( acc           == 'WRITE' ) &
              .and. ( ft%files(findex)%access /=  write  )  ) then
!
!           If the access type is 'WRITE', the DAS file must be open
!           for writing.
!
            call zzddhhlu ( ctx, handle, 'DAS', .false., number )

            call ctx%setmsg ( 'DAS file not open for writing. Handle = #,'// &
                          ' file = ''#''.'                             )
            call ctx%errint ( '#', handle                                  )
            call ctx%errfnm ( '#', number                                  )
            call ctx%sigerr ( 'SPICE(DASINVALIDACCESS)'                    )
            return

         end if

      end if

!
!     The DAS file's handle is o.k.
!
      return
      end associate
      end subroutine dassih

      !> Return the allowed access method for a specified DAS file.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE   is the handle of a previously opened DAS file.
      !>
      !>## Detailed Output
      !>
      !>     ACCESS   is a string indicating the type of access that
      !>              the DAS file specified by the input argument HANDLE
      !>              is open for. The values of ACCESS may be
      !>
      !>                 'READ'      File is open for read access by DAS
      !>                             routines. Both the data area and
      !>                             the comment area may be read. The
      !>                             file may not be modified.
      !>
      !>                 'WRITE'     File is open for write access by
      !>                             DAS routines. Files open for
      !>                             write access may be read as well as
      !>                             written.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If the input handle is invalid, the error SPICE(INVALIDHANDLE)
      !>         is signaled. ACCESS is not modified.
      !>
      !>## Files
      !>
      !>     None.
      !>
      !>## Particulars
      !>
      !>     This routine allows subroutines to determine the access methods
      !>     allowed for a given DAS file.
      !>
      !>## Examples
      !>
      !>     1)  Make sure that a file handle designates a DAS file that can
      !>         be read. Signal an error if not.
      !>
      !>         Note that if a DAS file is open for reading or writing, read
      !>         access is allowed.
      !>
      !>                  CALL DASHAM ( HANDLE, 'READ' )
      !>
      !>                  IF ( FAILED() ) THEN
      !>                     RETURN
      !>                  END IF
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     K.R. Gehringer     (JPL)
      !>     B.V. Semenov       (JPL)
      !>     W.L. Taber         (JPL)
      !>     I.M. Underwood     (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 6.0.2, 19-JUL-2021 (JDR)
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>-    SPICELIB Version 6.0.1, 17-JUL-2002 (BVS)
      !>
      !>        Added MAC-OSX environments.
      !>
      !>-    SPICELIB Version 5.0.4, 08-OCT-1999 (WLT)
      !>
      !>        The environment lines were expanded so that the supported
      !>        environments are now explicitly given. New
      !>        environments are WIN-NT
      !>
      !>-    SPICELIB Version 5.0.3, 16-SEP-1999 (NJB)
      !>
      !>        CSPICE environments were added. Some typos were corrected.
      !>
      !>-    SPICELIB Version 5.0.2, 28-JUL-1999 (WLT)
      !>
      !>        The environment lines were expanded so that the supported
      !>        environments are now explicitly given. New
      !>        environments are PC-DIGITAL, SGI-O32 and SGI-N32.
      !>
      !>-    SPICELIB Version 5.0.1, 18-MAR-1999 (WLT)
      !>
      !>        The environment lines were expanded so that the supported
      !>        environments are now explicitly given. Previously,
      !>        environments such as SUN-SUNOS and SUN-SOLARIS were implied
      !>        by the environment label SUN.
      !>
      !>-    SPICELIB Version 1.0.1, 01-NOV-1993 (KRG)
      !>
      !>        Removed references to specific DAS file open routines in the
      !>        $Detailed_Input and $ Output sections of the header. This was
      !>        done in order to minimize documentation changes if these open
      !>        routines ever change.
      !>
      !>-    SPICELIB Version 1.0.0, 01-FEB-1993 (NJB) (WLT) (IMU)
      !>
      !>## Revisions
      !>
      !>-    SPICELIB Version 1.0.1, 01-NOV-1993 (KRG)
      !>
      !>        Removed references to specific DAS file open routines in the
      !>        $Detailed_Input and $ Output sections of the header. This was
      !>        done in order to minimize documentation changes if these open
      !>        routines ever change.
      !>
      !>-    SPICELIB Version 1.0.0, 01-FEB-1993 (NJB) (WLT) (IMU)
      module subroutine dasham ( ctx, handle, access )
      use pepper_kinds, only: ip
      use pepper_inc_das
      use pepper_inc_errhnd
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! HANDLE of a DAS file.
      character(*), intent(out) :: access  !! String indicating allowed access method.
      integer(ip), parameter :: read = 1
      integer(ip), parameter :: next   ( 3 ) = &
         [ 2, 3, 1 ]
      integer(ip), parameter :: prev   ( 3 ) = &
         [ 3, 1, 2 ]
      character(acclen) :: acc
      character(fmtlen) :: format
      character(idwlen) :: idword
      character(ifnlen) :: locifn
      character(fmtlen) :: locfmt
      character(tailen) :: tail
      character(typlen) :: ttype
      integer(ip) :: curtyp
      integer(ip) :: dirrec ( nwi )
      integer(ip) :: dsctyp
      integer(ip) :: endrec
      integer(ip) :: fnb
      integer(ip) :: findex
      integer(ip) :: i
      integer(ip) :: inqsta
      integer(ip) :: iostat
      integer(ip) :: last
      integer(ip) :: ldrec  ( 3 )
      integer(ip) :: ldrmax
      integer(ip) :: loc
      integer(ip) :: loccch
      integer(ip) :: loccrc
      integer(ip) :: locrrc
      integer(ip) :: locrch
      integer(ip) :: maxadr
      integer(ip) :: new
      integer(ip) :: nrec
      integer(ip) :: number
      integer(ip), parameter :: nw     ( 3 ) = &
         [ nwc, nwd, nwi ]
      integer(ip) :: nxtdir
      integer(ip) :: nxtrec
      integer(ip) :: prvtyp
      integer(ip) :: type
      logical :: found
      associate ( ft => ctx%spice%dasfm )
!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     See whether the input handle is in our list at all.  It's
!     unlawful for the handle to be absent.
!
      findex  =  ft%find ( handle )
      found   =  findex > 0

      if ( .not. found ) then

         call ctx%setmsg ( 'The handle # does not designate a known DAS ' // &
                       'file '                                         )
         call ctx%errint ( '#',  handle                                    )
         call ctx%sigerr ( 'SPICE(INVALIDHANDLE)'                          )
         return

      end if

!
!     We know about the file if we got this far.  Set the output
!     argument accordingly.
!
      if (  ft%files(findex)%access == read ) then
         access = 'READ'
      else
         access = 'WRITE'
      end if

      return
      end associate
      end subroutine dasham

      !> Read DAS double precision physical records.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE   is the handle of an open DAS file.
      !>
      !>     RECNO    is the number of a record in a DAS file.
      !>
      !>     FIRST,
      !>     LAST     are the first and last indices of a range of
      !>              double precision numbers to be read from the
      !>              indicated record. The record contains NWD
      !>              double precision numbers; these have indices
      !>              ranging from 1 to NWD.
      !>
      !>## Detailed Output
      !>
      !>     DATAD    is a double precision array containing the
      !>              elements FIRST through LAST of the specified
      !>              record. The record element FIRST is placed
      !>              in DATAD(1), the record element FIRST+1 is placed
      !>              in DATAD(2), and so on; the record element LAST is
      !>              placed in DATAD(LAST-FIRST+1).
      !>
      !>## Parameters
      !>
      !>     NWD      is the number of DPs in a single DAS record
      !>              containing DPs.
      !>
      !>     BUFSZD   is the number of records in the double precision
      !>              record buffer.
      !>
      !>## Exceptions
      !>
      !>     1)  If the input file handle is invalid, an error is signaled by a
      !>         routine in the call tree of this routine. The output argument
      !>         DATAD will not be modified.
      !>
      !>     2)  If a read operation attempted by this routine fails, an error
      !>         is signaled by a routine in the call tree of this routine. The
      !>         output argument DATAD will not be modified.
      !>
      !>     3)  If a write operation attempted by this routine fails, an error
      !>         is signaled by a routine in the call tree of this routine. The
      !>         output argument DATAD will not be modified. This routine may
      !>         write out updated, buffered records in order to make room in
      !>         the double precision buffer for a newly read record. Note that
      !>         the file written to may be different than the file designated
      !>         by HANDLE if multiple DAS files are open for writing.
      !>
      !>     4)  If FIRST or LAST is not in the range [1, NWD], the error
      !>         SPICE(INDEXOUTOFRANGE) is signaled. The output argument
      !>         DATAD will not be modified.
      !>
      !>     5)  If FIRST > LAST, this routine will return without modifying
      !>         the output argument DATAD.
      !>
      !>## Files
      !>
      !>     See the description of the argument HANDLE in $Detailed_Input.
      !>
      !>## Particulars
      !>
      !>     Routines outside of SPICELIB will normally have no need to call
      !>     this routine.
      !>
      !>     This routine can be used to read from a DAS file that is open for
      !>     reading or for writing. Any buffered double precision record
      !>     can be read with this routine. In particular, records that have
      !>     been written to the DAS double precision record buffer but have
      !>     not yet been written out to the DAS file they're intended to go
      !>     to ARE visible to this routine.
      !>
      !>     This routine should be used to read only records that contain
      !>     double precision data.
      !>
      !>## Examples
      !>
      !>     1)  Read the 10th through 100th d.p. numbers from record number 9
      !>         in a DAS file designated by HANDLE.
      !>
      !>             CALL DASRRD ( HANDLE, 9, 10, 100, DATAD )
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     K.R. Gehringer     (JPL)
      !>     B.V. Semenov       (JPL)
      !>     W.L. Taber         (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 2.0.1, 22-FEB-2021 (JDR)
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>-    SPICELIB Version 2.0.0, 05-FEB-2015 (NJB)
      !>
      !>        Upgraded to support handle manager integration and
      !>        reading of non-native files.
      !>
      !>-    SPICELIB Version 1.1.1, 10-FEB-2014 (BVS)
      !>
      !>        Added description of NWD to the $Parameters and $Brief_I/O
      !>        sections of the header.
      !>
      !>-    SPICELIB Version 1.1.0, 03-NOV-1995 (NJB)
      !>
      !>        Made modifications to enhance efficiency. Removed references
      !>        to the function RETURN.
      !>
      !>        Removed weird spaces from ENTRY statement.
      !>
      !>-    SPICELIB Version 1.0.1, 28-OCT-1993 (KRG)
      !>
      !>        Removed references to specific DAS file open routines in the
      !>        $Detailed_Input section of the header. This was done in order
      !>        to minimize documentation changes if the DAS open routines ever
      !>        change.
      !>
      !>-    SPICELIB Version 1.0.0, 30-JUN-1992 (NJB) (WLT)
      !>
      !>## Revisions
      !>
      !>-    SPICELIB Version 1.1.0, 03-NOV-1995 (NJB)
      !>
      !>        Made modifications to enhance efficiency. Removed references
      !>        to the function RETURN. For buffered reads, MOVED is not
      !>        called when a single word is to be read.
      !>
      !>        Removed weird spaces from ENTRY statement.
      !>
      !>-    SPICELIB Version 1.0.1, 28-OCT-1993 (KRG)
      !>
      !>        Removed references to specific DAS file open routines in the
      !>        $Detailed_Input section of the header. This was done in order
      !>        to minimize documentation changes if the DAS open routines ever
      !>        change.
      !>
      !>-    SPICELIB Version 1.0.0, 30-JUN-1992 (NJB) (WLT)
      module subroutine dasrrd ( ctx, handle, recno, first, last, datad )
      use pepper_kinds, only: ip, wp
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! Handle of DAS file.
      integer(ip), intent(in) :: recno  !! Record number.
      integer(ip), intent(in) :: first  !! First and last indices of range within record.
      integer(ip), intent(in) :: last  !! First and last indices of range within record.
      real(wp), intent(out) :: datad   ( * )  !! Double precision data read from record.
      logical :: return
      integer(ip) :: node
      integer(ip) :: wrunit
      call files_check ( ctx )
      if ( .not. allocated ( ctx%dasrwr ) ) then
         allocate ( ctx%dasrwr )
         call init_dasrwr_state ( ctx%dasrwr )
      end if
      associate ( rcbufd => ctx%dasrwr%rcbufd, &
                  rnbufd => ctx%dasrwr%rnbufd, &
                  hnbufd => ctx%dasrwr%hnbufd, &
                  upbufd => ctx%dasrwr%upbufd, &
                  poolc => ctx%dasrwr%poolc, &
                  poold => ctx%dasrwr%poold, &
                  pooli => ctx%dasrwr%pooli, &
                  headd => ctx%dasrwr%headd, &
                  usedd => ctx%dasrwr%usedd, &
                  pass1 => ctx%dasrwr%pass1 )
!
!     If it hasn't been done yet, initialize the pointer list pools.
!
      if ( pass1 ) then

         call lnkini ( ctx, bufszd, poold )
         call lnkini ( ctx, bufszi, pooli )
         call lnkini ( ctx, bufszc, poolc )

         pass1  = .false.

      end if

!
!     Check FIRST and LAST.
!
      if (        ( first < 1   ) &
            .or.  ( first > nwd ) &
            .or.  ( last  < 1   ) &
            .or.  ( last  > nwd )    )  then

         call ctx%setmsg ( 'Array indices FIRST and LAST were #,  #; '    // &
                       'allowed range for both is [#, #]. File was '  // &
                       '#, record number was #.'                       )
         call ctx%errint ( '#',  first                                     )
         call ctx%errint ( '#',  last                                      )
         call ctx%errint ( '#',  1                                         )
         call ctx%errint ( '#',  nwd                                       )
         call ctx%errhan ( '#',  handle                                    )
         call ctx%errint ( '#',  recno                                     )
         call ctx%sigerr ( 'SPICE(INDEXOUTOFRANGE)'                        )
         return

      end if

!
!     There's nothing to do if LAST < FIRST.  (We're not checked in at
!     this point.)
!
      if ( last < first ) return

!
!     See whether record number RECNO in file HANDLE is buffered.  We'll
!     search through the list of buffered records starting at the head
!     of the list.  If we find the desired record, transfer the
!     requested data to the array DATAD and return without further ado.
!
      node = headd

      do while ( node > 0 )

         if (         (  handle == hnbufd(node)  ) &
               .and.  (  recno  == rnbufd(node)  )    )  then
!
!           Found it.  Move this record to the head of the list.
!           Update our head pointer as required.
!
            if ( node /= headd ) then

               call lnkxsl ( ctx, node, node,  poold )
               call lnkilb ( ctx, node, headd, poold )

               headd  =  node

            end if

!
!           Don't forget to return the requested data.
!
            if ( first == last ) then

               datad(1) = rcbufd( first, node )

            else

               datad(1:last-first+1) = rcbufd(first:last,node)

            end if

!
!           We haven't checked in, so don't check out.
!
            return

         end if

         node = poold ( forwrd, node )

      end do

!
!     The record wasn't buffered.  We need to allocate entries to
!     hold the record contents.  If the buffer isn't full, just
!     select a free set of entries.  If the buffer is full, use
!     the set of entries at the tail of the list.
!
!     Since we're now going to do a file read, it doesn't slow
!     us down much to check in, comparatively speaking.
!

      if (  usedd == bufszd ) then
!
!        Grab the buffer entry at the tail end of the list.
!
         node  =  lnktl ( ctx, headd, poold )

         call lnkxsl ( ctx, node, node, poold )

!
!        If the allocated buffer entry was updated, write it out.
!
         if (  upbufd(node)  ) then
!
!           We'll need a logical unit in order to write to the file.
!
            call zzddhhlu ( ctx, hnbufd(node), 'DAS', .false., wrunit )

            if ( ctx%failed() ) return

            call dasiod ( ctx, 'WRITE', &
                           wrunit, &
                           rnbufd(    node ), &
                           rcbufd( 1, node )  )

            if ( ctx%failed() ) return

         end if

      else
!
!        Allocate a new set of buffer entries, but don't link
!        them into the list yet.
!
         call lnkan  ( ctx, poold, node )
         usedd = usedd + 1

      end if

!
!     Try to read the record.
!
      call zzdasgrd ( ctx, handle, recno, rcbufd(1,node) )

      if ( ctx%failed() ) return

!
!     The read was successful.  Link the node pointing to the buffer
!     entries for this record in before the current head of the
!     list, thus putting them at the head.
!
!     Set the file handle, record number, and update flag for
!     this record.
!
      call lnkilb ( ctx, node, headd, poold )

      hnbufd ( node )  =  handle
      rnbufd ( node )  =  recno
      upbufd ( node )  =  .false.
      headd            =  node

!
!     Don't forget to return the requested data.
!
      datad(1:last  -  first + 1) = rcbufd(first:last,node)

      return
      end associate
      end subroutine dasrrd

      !> Read DAS integer physical records.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE   is the handle of an open DAS file.
      !>
      !>     RECNO    is the number of a record in a DAS file.
      !>
      !>     FIRST,
      !>     LAST     are the first and last indices of a range of
      !>              integers to be read from the indicated record.
      !>              The record contains NWI integers; these have
      !>              indices ranging from 1 to NWI.
      !>
      !>## Detailed Output
      !>
      !>     DATAI    is an integer array containing the elements FIRST
      !>              through LAST of the specified record. The record
      !>              element FIRST is placed in DATAI(1), the record
      !>              element FIRST+1 is placed in DATAI(2), and so on;
      !>              the record element LAST is placed in
      !>              DATAI(LAST-FIRST+1).
      !>
      !>## Parameters
      !>
      !>     NWI      is the number of integers in a single DAS record
      !>              containing integers.
      !>
      !>     BUFSZI   is the number of records in the integer record
      !>              buffer.
      !>
      !>## Exceptions
      !>
      !>     1)  If the input file handle is invalid, an error is signaled
      !>         by a routine in the call tree of this routine. The
      !>         output argument DATAI will not be modified.
      !>
      !>     2)  If a read operation attempted by this routine fails, an error
      !>         is signaled by a routine in the call tree of this routine.
      !>         The output argument DATAI will not be modified.
      !>
      !>     3)  If a write operation attempted by this routine fails, an
      !>         error is signaled by a routine in the call tree of this
      !>         routine. The output argument DATAI will not be modified. This
      !>         routine may write out updated, buffered records in order to
      !>         make room in the integer buffer for a newly read record. Note
      !>         that the file written to may be different than the file
      !>         designated by HANDLE if multiple DAS files are open for
      !>         writing.
      !>
      !>     4)  If FIRST or LAST is not in the range [1, NWI], the error
      !>         SPICE(INDEXOUTOFRANGE) is signaled. The output argument
      !>         DATAI will not be modified.
      !>
      !>     5)  If FIRST > LAST, this routine will return without modifying
      !>         the output argument DATAI.
      !>
      !>## Files
      !>
      !>     See the description of the argument HANDLE in $Detailed_Input.
      !>
      !>## Particulars
      !>
      !>     Routines outside of SPICELIB will normally have no need to call
      !>     this routine.
      !>
      !>     This routine can be used to read from a DAS file that is open for
      !>     reading or writing. Any buffered integer record can be read with
      !>     this routine. In particular, records that have been written to
      !>     the DAS integer record buffer but have not yet been written out
      !>     to the DAS file they're intended to go to ARE visible to this
      !>     routine.
      !>
      !>     This routine should be used to read only records that contain
      !>     integer data.
      !>
      !>## Examples
      !>
      !>     1)  Read the 10th through 100th integers from record number 9
      !>         in a DAS file designated by HANDLE.
      !>
      !>             CALL DASRRI ( HANDLE, 9, 10, 100, DATAI )
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     K.R. Gehringer     (JPL)
      !>     B.V. Semenov       (JPL)
      !>     W.L. Taber         (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 2.0.1, 22-FEB-2021 (JDR)
      !>
      !>        Updated the header to comply with NAIF standard. Cleaned up
      !>        the $Revisions history.
      !>
      !>-    SPICELIB Version 2.0.0, 05-FEB-2015 (NJB)
      !>
      !>        Upgraded to support handle manager integration and
      !>        reading of non-native files.
      !>
      !>-    SPICELIB Version 1.1.1, 10-FEB-2014 (BVS)
      !>
      !>        Added description of NWI to the $Parameters and $Brief_I/O
      !>        sections of the header.
      !>
      !>-    SPICELIB Version 1.1.0, 03-NOV-1995 (NJB)
      !>
      !>        Made modifications to enhance efficiency. Removed references
      !>        to the function RETURN.
      !>
      !>        Removed weird spaces from ENTRY statement.
      !>
      !>-    SPICELIB Version 1.0.1, 28-OCT-1993 (KRG)
      !>
      !>        Removed references to specific DAS file open routines in the
      !>        $Detailed_Input section of the header. This was done in order
      !>        to minimize documentation changes if the DAS open routines ever
      !>        change.
      !>
      !>-    SPICELIB Version 1.0.0, 30-JUN-1992 (NJB) (WLT)
      !>
      !>## Revisions
      !>
      !>-    SPICELIB Version 2.0.0, 05-FEB-2015 (NJB)
      !>
      !>        Upgraded to support handle manager integration and
      !>        reading of non-native files.
      !>
      !>-    SPICELIB Version 1.1.0, 03-NOV-1995 (NJB)
      !>
      !>        Made modifications to enhance efficiency. Removed references
      !>        to the function RETURN. For buffered reads, MOVEI is not
      !>        called when a single word is to be read.
      module subroutine dasrri ( ctx, handle, recno, first, last, datai )
      use pepper_kinds, only: ip, wp
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! Handle of DAS file.
      integer(ip), intent(in) :: recno  !! Record number.
      integer(ip), intent(in) :: first  !! First and last indices of range within record.
      integer(ip), intent(in) :: last  !! First and last indices of range within record.
      integer(ip), intent(out) :: datai   ( * )  !! Integer data read from record.
      logical :: return
      integer(ip) :: node
      integer(ip) :: wrunit
      call files_check ( ctx )
      if ( .not. allocated ( ctx%dasrwr ) ) then
         allocate ( ctx%dasrwr )
         call init_dasrwr_state ( ctx%dasrwr )
      end if
      associate ( rcbufi => ctx%dasrwr%rcbufi, &
                  rnbufi => ctx%dasrwr%rnbufi, &
                  hnbufi => ctx%dasrwr%hnbufi, &
                  upbufi => ctx%dasrwr%upbufi, &
                  poolc => ctx%dasrwr%poolc, &
                  poold => ctx%dasrwr%poold, &
                  pooli => ctx%dasrwr%pooli, &
                  headi => ctx%dasrwr%headi, &
                  usedi => ctx%dasrwr%usedi, &
                  pass1 => ctx%dasrwr%pass1 )
!
!     If it hasn't been done yet, initialize the pointer list pools.
!
      if ( pass1 ) then

         call lnkini ( ctx, bufszd, poold )
         call lnkini ( ctx, bufszi, pooli )
         call lnkini ( ctx, bufszc, poolc )

         pass1  = .false.

      end if

!
!     Check FIRST and LAST.
!
      if (        ( first < 1   ) &
            .or.  ( first > nwi ) &
            .or.  ( last  < 1   ) &
            .or.  ( last  > nwi )    )  then

         call ctx%setmsg ( 'Array indices FIRST and LAST were #,  #; '    // &
                       'allowed range for both is [#, #]. File was '  // &
                       '#, record number was #.'                       )
         call ctx%errint ( '#',  first                                     )
         call ctx%errint ( '#',  last                                      )
         call ctx%errint ( '#',  1                                         )
         call ctx%errint ( '#',  nwi                                       )
         call ctx%errhan ( '#',  handle                                    )
         call ctx%errint ( '#',  recno                                     )
         call ctx%sigerr ( 'SPICE(INDEXOUTOFRANGE)'                        )
         return

      end if

!
!     There's nothing to do if LAST < FIRST.  (We're not checked in at
!     this point.)
!
      if ( last < first ) return

!
!     See whether record number RECNO in file HANDLE is buffered.  We'll
!     search through the list of buffered records starting at the head
!     of the list.  If we find the desired record, transfer the
!     requested data to the array DATAI and return without further ado.
!
      node = headi

      do while ( node > 0 )

         if (         (  handle == hnbufi(node)  ) &
               .and.  (  recno  == rnbufi(node)  )    )  then
!
!           Found it.  Move this record to the head of the list.
!           Update our head pointer as required.
!
            if ( node /= headi ) then

               call lnkxsl ( ctx, node, node,  pooli )
               call lnkilb ( ctx, node, headi, pooli )

               headi  =  node

            end if

!
!           Don't forget to return the requested data.
!
            if ( first == last ) then

               datai(1) = rcbufi( first, node )

            else

               datai(1:last-first+1) = rcbufi(first:last,node)

            end if

!
!           We haven't checked in, so don't check out.
!
            return

         end if

         node = pooli ( forwrd, node )

      end do

!
!     The record wasn't buffered.  We need to allocate entries to
!     hold the record contents.  If the buffer isn't full, just
!     select a free set of entries.  If the buffer is full, use
!     the set of entries at the tail of the list.
!
!     Since we're now going to do a file read, it doesn't slow
!     us down much to check in, comparatively speaking.
!

      if (  usedi == bufszi ) then
!
!        Grab the buffer entry at the tail end of the list.
!
         node  =  lnktl ( ctx, headi, pooli )

         call lnkxsl ( ctx, node, node, pooli )

!
!        If the allocated buffer entry was updated, write it out.
!
         if (  upbufi(node)  ) then

            call zzddhhlu ( ctx, hnbufi(node), 'DAS', .false., wrunit )

            call dasioi ( ctx, 'WRITE', &
                          wrunit, &
                          rnbufi(    node ), &
                          rcbufi( 1, node )   )

            if ( ctx%failed() ) return

         end if

      else
!
!        Allocate a new set of buffer entries, but don't link
!        them into the list yet.
!
         call lnkan ( ctx, pooli, node )
         usedi = usedi + 1

      end if

!
!     Try to read the record.
!
      call zzdasgri ( ctx, handle,  recno,  rcbufi(1,node)  )

      if ( ctx%failed() ) return

!
!     The read was successful.  Link the node pointing to the buffer
!     entries for this record in before the current head of the
!     list, thus putting them at the head.
!
!     Set the file handle, record number, and update flag for
!     this record.
!
      call lnkilb ( ctx, node, headi, pooli )

      hnbufi ( node )  =  handle
      rnbufi ( node )  =  recno
      upbufi ( node )  =  .false.
      headi            =  node

!
!     Don't forget to return the requested data.
!
      datai(1:last  -  first + 1) = rcbufi(first:last,node)

      return
      end associate
      end subroutine dasrri

      !> Read DAS character physical records.
      !>
