      !>
      !>        Upgraded to support handle manager integration.
      !>
      !>-    SPICELIB Version 1.1.0, 09-NOV-1995 (NJB)
      !>
      !>        Made modifications to enhance efficiency. Removed references
      !>        to the function RETURN.
      module subroutine dasrrc ( ctx, handle, recno, first, last, datac )
      use pepper_kinds, only: ip, wp
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! Handle of DAS file.
      integer(ip), intent(in) :: recno  !! Record number.
      integer(ip), intent(in) :: first  !! First and last indices of range within record.
      integer(ip), intent(in) :: last  !! First and last indices of range within record.
      character(*), intent(out) :: datac  !! Character data read from record.
      logical :: return
      integer(ip) :: node
      integer(ip) :: unit
      integer(ip) :: wrunit
      call files_check ( ctx )
      if ( .not. allocated ( ctx%dasrwr ) ) then
         allocate ( ctx%dasrwr )
         call init_dasrwr_state ( ctx%dasrwr )
      end if
      associate ( rcbufc => ctx%dasrwr%rcbufc, &
                  rnbufc => ctx%dasrwr%rnbufc, &
                  hnbufc => ctx%dasrwr%hnbufc, &
                  upbufc => ctx%dasrwr%upbufc, &
                  poolc => ctx%dasrwr%poolc, &
                  poold => ctx%dasrwr%poold, &
                  pooli => ctx%dasrwr%pooli, &
                  headc => ctx%dasrwr%headc, &
                  usedc => ctx%dasrwr%usedc, &
                  pass1 => ctx%dasrwr%pass1 )
!
!     If it hasn't been done yet, initialize the pointer list pools.
!
      if ( pass1 ) then

         call lnkini ( ctx, bufszd, poold )
         call lnkini ( ctx, bufszi, pooli )
         call lnkini ( ctx, bufszc, poolc )

         pass1  = .false.

      end if

!
!     Check FIRST and LAST.
!
      if (        ( first < 1   ) &
            .or.  ( first > nwc ) &
            .or.  ( last  < 1   ) &
            .or.  ( last  > nwc )    )  then

         call ctx%setmsg ( 'Array indices FIRST and LAST were #,  #; '    // &
                       'allowed range for both is [#, #]. File was '  // &
                       '#, record number was #.'                       )
         call ctx%errint ( '#',  first                                     )
         call ctx%errint ( '#',  last                                      )
         call ctx%errint ( '#',  1                                         )
         call ctx%errint ( '#',  nwc                                       )
         call ctx%errhan ( '#',  handle                                    )
         call ctx%errint ( '#',  recno                                     )
         call ctx%sigerr ( 'SPICE(INDEXOUTOFRANGE)'                        )
         return

      end if

!
