      module subroutine daswri ( ctx, handle, recno, reci )
      use pepper_kinds, only: ip, wp
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! Handle of DAS file.
      integer(ip), intent(in) :: recno  !! Record number.
      integer(ip), intent(in) :: reci    ( nwi )  !! Integer data to be written to record.
      integer(ip) :: node
      integer(ip) :: unit
      integer(ip) :: wrunit
      call files_check ( ctx )
      if ( .not. allocated ( ctx%dasrwr ) ) then
         allocate ( ctx%dasrwr )
         call init_dasrwr_state ( ctx%dasrwr )
      end if
      associate ( rcbufi => ctx%dasrwr%rcbufi, &
                  rnbufi => ctx%dasrwr%rnbufi, &
                  hnbufi => ctx%dasrwr%hnbufi, &
                  upbufi => ctx%dasrwr%upbufi, &
                  poolc => ctx%dasrwr%poolc, &
                  poold => ctx%dasrwr%poold, &
                  pooli => ctx%dasrwr%pooli, &
                  headi => ctx%dasrwr%headi, &
                  usedi => ctx%dasrwr%usedi, &
                  pass1 => ctx%dasrwr%pass1 )
!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Check that the file is open for writing.  Signal an error if not.
